def solve():
    n = int(input())
    sequence = input().strip()

    slavko_word = ""
    for i in range(n):
        if i % 2 == 1:
            slavko_word = sequence[-1] + slavko_word
        sequence = sequence[:-1]

    print("DA" if n % 2 == 0 else "NE")
    print(slavko_word)

if __name__ == "__main__":
    solve()

import sys

def slavko_game(N, sequence):
    slavko_word = ""
    while sequence:
        slavko_word += sequence[-1]
        sequence = sequence[:-1]

    mirko_word = ""
    sequence = sequence[::-1]
    while sequence:
        mirko_word += sequence[-1]
        sequence = sequence[:-1]

    if slavko_word > mirko_word:
        print("DA")
    else:
        print("NE")
    print(slavko_word)

if __name__ == "__main__":
    N = int(sys.stdin.readline().strip())
    sequence = sys.stdin.readline().strip()
    slavko_game(N, sequence)
